import pandas as pd

def solve(data):
     clean = pd.Series(data['names'], dtype='string').str.strip().str.lower().fillna('unknown')
     mask = clean.str.contains(data['query'], regex=False, na=False)
     return {'clean': clean.tolist(), 'matched': clean.loc[mask].tolist()}
